-- 6 TABLAS, 4 VISTAS, 4,769 registros totales
-- =============================================================

PRAGMA foreign_keys = ON;

-- TABLA 1: materiales (204 registros)
DROP TABLE IF EXISTS materiales;
CREATE TABLE materiales (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    item             INTEGER,
    codigo           INTEGER UNIQUE NOT NULL,
    descripcion      TEXT    NOT NULL,
    unidad           TEXT,
    precio_igmelec   REAL,
    precio_grape     REAL,
    precio_bellon    REAL,
    precio_ochoa     REAL,
    precio_maenca    REAL,
    precio_transdeci REAL
);
CREATE INDEX idx_materiales_codigo ON materiales(codigo);

-- TABLA 2: estructuras_catalogo (525 registros)
DROP TABLE IF EXISTS estructuras_catalogo;
CREATE TABLE estructuras_catalogo (
    id     INTEGER PRIMARY KEY AUTOINCREMENT,
    nombre TEXT NOT NULL UNIQUE,
    tipo   TEXT
);
CREATE INDEX idx_estructuras_tipo ON estructuras_catalogo(tipo);

-- TABLA 3: estructuras_mano_obra (69 registros)
DROP TABLE IF EXISTS estructuras_mano_obra;
CREATE TABLE estructuras_mano_obra (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    descripcion TEXT NOT NULL,
    precio      REAL,
    itbis       REAL,
    total       REAL
);

-- TABLA 4: uucc_material_estructura (4,055 registros) <-- EL CORAZON DEL UUCC
DROP TABLE IF EXISTS uucc_material_estructura;
CREATE TABLE uucc_material_estructura (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    estructura       TEXT NOT NULL,
    codigo_material  INTEGER NOT NULL REFERENCES materiales(codigo),
    descripcion      TEXT,
    cantidad         REAL,
    total_uso        REAL
);
CREATE INDEX idx_uucc_estructura ON uucc_material_estructura(estructura);
CREATE INDEX idx_uucc_codigo ON uucc_material_estructura(codigo_material);

-- TABLA 5: totales_materiales (204 registros)
DROP TABLE IF EXISTS totales_materiales;
CREATE TABLE totales_materiales (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    codigo_material INTEGER UNIQUE REFERENCES materiales(codigo),
    descripcion     TEXT,
    total           REAL
);

-- TABLA 6: analisis_costo_estructura (115 registros)
DROP TABLE IF EXISTS analisis_costo_estructura;
CREATE TABLE analisis_costo_estructura (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    estructura      TEXT,
    codigo_material INTEGER REFERENCES materiales(codigo),
    descripcion     TEXT,
    cantidad        REAL,
    unidad          TEXT,
    precio_unitario REAL,
    subtotal        REAL GENERATED ALWAYS AS (
        CASE WHEN cantidad IS NOT NULL AND precio_unitario IS NOT NULL
             THEN ROUND(cantidad * precio_unitario, 2)
             ELSE NULL END
    ) VIRTUAL
);


