-- ===== VISTAS =====

-- Precio de referencia consolidado por material
CREATE VIEW IF NOT EXISTS v_materiales_precio AS
SELECT codigo, descripcion, unidad,
       COALESCE(precio_igmelec, precio_grape, precio_bellon, precio_ochoa) AS precio_referencia,
       precio_igmelec, precio_grape, precio_bellon, precio_ochoa, precio_maenca, precio_transdeci
FROM materiales;

-- Costo total de materiales por estructura en analisis
CREATE VIEW IF NOT EXISTS v_costo_por_estructura AS
SELECT estructura, COUNT(*) AS cant_items,
       ROUND(SUM(subtotal), 2) AS costo_materiales_total
FROM analisis_costo_estructura
WHERE subtotal IS NOT NULL
GROUP BY estructura;

-- Materiales con precio + uso total
CREATE VIEW IF NOT EXISTS v_materiales_uso_total AS
SELECT m.codigo, m.descripcion, m.unidad,
       COALESCE(m.precio_igmelec, m.precio_grape) AS precio_ref,
       COALESCE(t.total, 0) AS total_unidades,
       ROUND(COALESCE(t.total,0) * COALESCE(m.precio_igmelec,m.precio_grape,0), 2) AS costo_estimado
FROM materiales m
LEFT JOIN totales_materiales t ON m.codigo = t.codigo_material
ORDER BY costo_estimado DESC;

-- Costo UUCC: para cada estructura del catalogo UUCC, suma cantidad*precio
CREATE VIEW IF NOT EXISTS v_costo_uucc_por_estructura AS
SELECT u.estructura,
       COUNT(DISTINCT u.codigo_material) AS materiales_distintos,
       SUM(u.cantidad) AS cantidad_total,
       ROUND(SUM(u.cantidad * COALESCE(m.precio_igmelec,m.precio_grape,0)), 2) AS costo_materiales_rd
FROM uucc_material_estructura u
LEFT JOIN materiales m ON u.codigo_material = m.codigo
GROUP BY u.estructura
ORDER BY costo_materiales_rd DESC;
